// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // Fuzzed parameter: an arbitrary caller address (the fuzzer will supply many addresses).
    // General rule: owner() must always return the deployer address (address(this) passed to constructor).
    // The mutant that returns address(0) will cause this assertion to fail for many inputs.
    function testFuzz_property(address anyCaller) public {
        // keep domain wide but avoid zero-address caller collisions with constructor owner check not needed
        // No vm.assume to keep it fully wide; we only call owner() getter (view) which doesn't depend on caller

        // Call owner() from arbitrary caller to ensure the external observable value is consistent
        bool ok;
        try c.owner() returns (address returned) {
            // Check that the returned owner equals the address passed in constructor (address(this))
            // This must hold for the reference contract for all inputs.
            ok = (returned == address(this));
        } catch {
            // If call reverts (shouldn't), mark as not ok
            ok = false;
        }

        // Single assertion: reference satisfies this for all inputs; mutant that returns address(0) will fail
        assertTrue(ok);
    }
}

