pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer = address(this);

    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    function testFuzz_property(address caller) public {
        // Keep wide domain but avoid the zero address subtlety of fuzzing frameworks if needed
        vm.assume(caller != address(0));

        // The general rule: the reference's owner() should always equal the deployer (address(this) when constructed).
        // We call owner() as any caller (the returned owner should not depend on msg.sender) and assert equality.
        // This will pass on the reference and fail on the mutant which returns address(0).

        // Call the view to read owner; use try/catch to satisfy the instructions in case of revert differences.
        bool ok;
        address readOwner;
        try c.owner{gas: 100000}() returns (address o) {
            ok = true;
            readOwner = o;
        } catch {
            ok = false;
            readOwner = address(0);
        }

        // Single assertion: owner() must be callable (ok==true) and equal to the deployer
        assertTrue(ok && readOwner == deployer);
    }
}

