pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // fuzzed parameter is the candidate newOwner to transfer ownership to
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no exclusion so fuzzer can pick zero address
        // ensure caller is current owner (this contract) for the call
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract enforces that if transferOwnership succeeds then owner() == newOwner.
        // Also, in the correct contract transferOwnership reverts when newOwner == address(0),
        // so for newOwner == address(0) the call should have failed (ok == false).
        // Therefore the universal property we assert is:
        //   either the call reverted (ok == false), or owner() equals newOwner.
        // This holds for all inputs on the reference implementation; the mutant that omits
        // the zero-address require will allow ok == true and owner() == address(0) for
        // newOwner == address(0), which still satisfies the OR, so to ensure distinction
        // we rely on the fact that the correct contract never sets owner() to address(0)
        // after transferOwnership: express stronger universal rule: after the call, owner()
        // must never be address(0).
        // That is true for reference (it either reverts or sets to non-zero new owner).

        // single assertion reading c's public surface: owner() must not be zero address
        // after the attempted transfer; this fails on mutant when newOwner == address(0)
        // and the call succeeded.
        assertTrue(c.owner() != address(0));
    }
}

