pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // fuzz the candidate newOwner address; the distinguishing case is when newOwner == owner()
    function testFuzz_property(address newOwner) public {
        // keep wide domain but constrain to avoid the zero-address special case if desired
        // (the reference allows transferring to same owner and also rejects zero address via require)
        // We do not exclude zero because behavior for zero differs in both as well but the mutant
        // specifically adds a check for same-as-current owner which we want fuzzer to explore.

        // OnlyOwner guard: ensure the call is made by the current owner (this contract deployed c, so owner==address(this))
        // call transferOwnership as owner
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): In the reference implementation, calling transferOwnership
        // from the current owner with any address (including the same as current owner) does NOT revert
        // except when newOwner == address(0) which reverts; however the mutant additionally reverts when
        // newOwner == owner() — so we assert that if newOwner equals the current owner, the call must succeed.
        // We implement that by reading owner() and checking the call result when newOwner == owner().
        address currentOwner = c.owner();
        // exactly one assertion reading c's public surface
        assertTrue(!(newOwner == currentOwner) || ok);
    }
}

