import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // fuzzed input is the candidate new operator address
    function testFuzz_property(address newOp) public {
        // keep domain wide but avoid zero address to ensure meaningful change
        vm.assume(newOp != address(0));

        // caller must be owner (setUp deployed with owner = address(this))
        // call setOperator as owner
        bool ok;
        try c.setOperator(newOp) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: after a successful call (ok==true), the operator getter equals the supplied newOp.
        // This is the universal property the reference satisfies; the mutant that only emits an event will fail for some newOp.
        if (ok) {
            assertTrue(c.operator() == newOp);
        } else {
            // If the call reverted (shouldn't for correct contract), still assert that operator wasn't set to newOp
            // This keeps the single assertTrue requirement by observing a public getter; in practice on correct contract ok==true.
            assertTrue(c.operator() != newOp);
        }
    }
}

